import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BAOEAOnu.js";const u=JSON.parse('{"title":"Sobre","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/about.md","filePath":"getting-started/about.md","lastUpdated":1781623519000}'),r={name:"getting-started/about.md"};function d(i,e,n,c,l,m){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="sobre" tabindex="-1">Sobre <a class="header-anchor" href="#sobre" aria-label="Permalink to &quot;Sobre&quot;">​</a></h1><p><strong>Se Liga AI</strong> é um framework <em>spec-driven</em> para assistentes de código com IA. Ele padroniza o ciclo de desenvolvimento de features — da descoberta de requisitos ao merge — em <strong>comandos</strong> (workflows), <strong>skills</strong> (conhecimento de domínio) e <strong>scripts</strong> (runtime determinístico), funcionando no mesmo formato em vários CLIs.</p><blockquote><p>O método interno usa o prefixo <strong><code>sl</code></strong>: comandos como <code>/sl.plan</code>, skills como <code>sl-ux-design</code>, runtime em <code>.codesl/</code>.</p></blockquote><h2 id="o-problema-que-ele-resolve" tabindex="-1">O problema que ele resolve <a class="header-anchor" href="#o-problema-que-ele-resolve" aria-label="Permalink to &quot;O problema que ele resolve&quot;">​</a></h2><p>Assistentes de IA são ótimos gerando código, mas inconsistentes no <strong>processo</strong>: pulam requisitos, não seguem convenções do projeto, perdem contexto entre sessões. O Se Liga AI impõe um <strong>fluxo repetível</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requisitos (about.md) → plano (plan.md) → execução → revisão até 100% → entrega</span></span></code></pre></div><p>Cada etapa é um comando; cada comando carrega as skills certas e chama scripts que garantem o que não pode ficar a cargo do modelo (IDs de feature, status, changelog, merge).</p><h2 id="as-tres-camadas" tabindex="-1">As três camadas <a class="header-anchor" href="#as-tres-camadas" aria-label="Permalink to &quot;As três camadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Camada</th><th>O que é</th><th>Onde vive</th></tr></thead><tbody><tr><td><strong>Comandos</strong></td><td>Pontos de entrada / workflows (<code>/sl.plan</code>, <code>/sl.build</code>…)</td><td><code>.claude/commands</code>, <code>.codex/prompts</code>, skills nos demais</td></tr><tr><td><strong>Skills</strong></td><td>Conhecimento de domínio carregado por relevância</td><td><code>&lt;provider&gt;/skills/sl-*</code></td></tr><tr><td><strong>Runtime</strong></td><td>Scripts determinísticos (status, IDs, merge)</td><td><code>.codesl/scripts</code></td></tr></tbody></table><h2 id="principios" tabindex="-1">Princípios <a class="header-anchor" href="#principios" aria-label="Permalink to &quot;Princípios&quot;">​</a></h2><ul><li><strong>Spec-driven:</strong> a documentação dirige o código, não o contrário.</li><li><strong>Cross-agent:</strong> <code>SKILL.md</code> é um padrão comum — a mesma skill roda em Claude, Codex, Grok e Antigravity sem modificação.</li><li><strong>Determinístico onde importa:</strong> o que precisa ser repetível vira script, não prompt.</li><li><strong>Idioma do usuário:</strong> responde no seu idioma; termos técnicos em inglês.</li></ul><h2 id="origem" tabindex="-1">Origem <a class="header-anchor" href="#origem" aria-label="Permalink to &quot;Origem&quot;">​</a></h2><p>O Se Liga AI é um clone rebrandeado do método <strong>code-addiction v0.4.0</strong>. Tudo que era <code>add</code> virou <code>sl</code> e o runtime <code>.codeadd/</code> virou <code>.codesl/</code>, tornando-o independente e coexistível com o original. Veja <a href="/se-liga-ai-framework/deep-dive/providers">Providers</a> e <a href="/se-liga-ai-framework/deep-dive/project-structure">Runtime &amp; Estrutura</a> para os detalhes.</p>',13)])])}const g=o(r,[["render",d]]);export{u as __pageData,g as default};
